VALUES ('pte_lst_el_05', 'ptt_lst_elements', 'p07', $v$電極（チタン＋イリジウムめっき）$v$, NULL, NULL, $v$電極はチタンにイリジウムめっきを施した高価な部材。使用量を減らす小面積電極の特許がある$v$, NULL, $v$出力(電流)を下げるとスタック数が増え、電極を含む装置側の費用が増える。回収液側の電極が黒く変色した例(酸化の疑い、6月のラボ再組立て時)がある。$v$, DATE '2026-07-29', 'medium', 'meeting', $v$2026-07-29 LiSTie経営会議（Notion文字起こし）$v$, $v$小面積電極が実機で回収速度を保ったまま面積を減らせるか、黒変の原因を確かめる。$v$, 50, 'amie', 'amie', false, NULL)
