INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_06', 'ptt_lst_elements', 'p07', $v$セル・スタックの構造と試験$v$, NULL, NULL, $v$PEEK(耐熱樹脂)製のフィルタープレス式セルスタックが完成。室温の水通しで液漏れなし$v$, NULL, $v$電極は未搭載で、高温・強アルカリの通液と通電下の試験は未実施。電極を入れると膨らみ別の不具合が出る懸念。実機は膜約5,000枚で、1枚の交換に約10分では交換しきれず、交換しやすい構造が課題。$v$, DATE '2026-09-30', 'high', 'meeting', $v$2026-09-30 LiSTie取締役会（Notion文字起こし）ほか$v$, $v$高温・強アルカリの通液と、電極搭載後の膨らみ・液漏れを確かめる。フィルタープレス式=外側の板で締め付ける方式。$v$, 60, 'amie', 'amie', false, NULL)
