INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_07', 'ptt_lst_elements', 'p07', $v$標準セルと膜・電極の距離$v$, NULL, NULL, $v$誰が組み立てても同じ状態になる標準セルを設計(押さえ具で圧着し、シールを兼ねる)$v$, NULL, $v$従来のセルは組み方で電極と膜の距離が変わり、組み手の熟練度が結果に影響した。距離を0〜1mmから約2mmに離しても膜が割れ、接触が原因との仮説には否定的。$v$, DATE '2026-07-29', 'high', 'meeting', $v$2026-07-29 LiSTie経営会議（Notion文字起こし）ほか$v$, $v$標準セルで割れの原因候補(電圧・温度・電流の中心部集中)を切り分ける。$v$, 70, 'amie', 'amie', false, NULL)
ON CONFLICT (tech_entry_id) DO UPDATE SET tech_topic_id = EXCLUDED.tech_topic_id, row_label = EXCLUDED.row_label, value_min = EXCLUDED.value_min, value_max = EXCLUDED.value_max, value_text = EXCLUDED.value_text, unit = EXCLUDED.unit, condition_text = EXCLUDED.condition_text, observed_on = EXCLUDED.observed_on, confidence = EXCLUDED.confidence, source_kind = EXCLUDED.source_kind, source_ref = EXCLUDED.source_ref, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order, needs_check = EXCLUDED.needs_check, check_reason = EXCLUDED.check_reason, updated_by = 'amie', updated_at = NOW();

INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_08', 'ptt_lst_elements', 'p07', $v$デモスタックの電流目標（50Aの単位）$v$, 50, 50, $v$平均50A(目標)。50Aが膜1枚・セル・スタック全体のどれかは資料にない$v$, $v$A$v$, $v$8月資料は『平均50A/セル』(セルは膜25枚を収納、進捗評価は『晴れ』)。2号機の代表目標は『膜1枚で10A』で数え方が揃わない。1月の会議は『スタックで平均50Aは出るが長期は自信なし』。$v$, DATE '2026-08-26', 'low', 'estimate', $v$2026年8月取締役会資料 p.1$v$, $v$50Aの単位を定義し、必要な電源容量とスタック数の見積に反映する。$v$, 80, 'amie', 'amie', true, $v$50Aは、8月資料で『平均50A/セル』(膜25枚を収納)、1月の会議で『スタックで平均50A』、2号機の目標で『膜1枚で10A』と数え方が揃わない。どれかで必要な電源容量とスタック数の見積が変わるため、技術開発部に50Aが膜1枚・25枚・スタック全体のどれかを確認する。$v$)
