INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_09', 'ptt_lst_elements', 'p07', $v$電源（膜1枚ごとの通電と直並列）$v$, NULL, NULL, $v$膜1枚ごとに通電するため電源が大型化。直列と並列を組み合わせる接続方式を出願対象とした$v$, NULL, $v$普通の電気透析は電源1つで膜が何枚も入る。ホルダー(膜を複数枚並べた筐体)10個を全直列で約100V、全並列では太いケーブルが必要(概算)。直列5個ほどの塊を並列にするのが理想。$v$, DATE '2026-01-21', 'medium', 'meeting', $v$2026-01-21 LiSTie取締役会（Notion文字起こし）$v$, $v$実機の電流・電圧から直列の塊の個数を決め、電源容量を確かめる。$v$, 90, 'amie', 'amie', false, NULL)
ON CONFLICT (tech_entry_id) DO UPDATE SET tech_topic_id = EXCLUDED.tech_topic_id, row_label = EXCLUDED.row_label, value_min = EXCLUDED.value_min, value_max = EXCLUDED.value_max, value_text = EXCLUDED.value_text, unit = EXCLUDED.unit, condition_text = EXCLUDED.condition_text, observed_on = EXCLUDED.observed_on, confidence = EXCLUDED.confidence, source_kind = EXCLUDED.source_kind, source_ref = EXCLUDED.source_ref, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order, needs_check = EXCLUDED.needs_check, check_reason = EXCLUDED.check_reason, updated_by = 'amie', updated_at = NOW();

INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_10', 'ptt_lst_elements', 'p07', $v$自動制御と連続運転（社内報告）$v$, NULL, NULL, $v$濃度・pH・温度を自動制御する1号機をTYKに設置済み。最適条件での500時間連続運転はこれから$v$, NULL, $v$TYKの実証は量やコストでなくシステム確立が目的。配管のシリカ析出による停止、接続部の液漏れ、ヒーター配線の腐食が続き、間欠運転に切り替えて検証する計画。$v$, DATE '2026-09-30', 'medium', 'meeting', $v$2026-09-30 LiSTie取締役会（Notion文字起こし）ほか$v$, $v$500時間の連続運転で、電圧オン/オフ運転による膜性能の持続と、配管スケール(析出物)・液漏れの再発を確かめる。$v$, 100, 'amie', 'amie', true, $v$社外向けの見学会資料は『365日の連続運転が可能な装置が完成』、社内の8月取締役会資料は『運転再開が遅れ、連続運転条件の探索に時間を要する』で、装置の成熟度の説明が食い違う。対外説明にどちらを採るかが変わるため、技術開発部にこれまでの最長連続運転時間と条件を確認する(「連続運転の社外向け説明（見学会資料）」の行)。$v$)
ON CONFLICT (tech_entry_id) DO UPDATE SET tech_topic_id = EXCLUDED.tech_topic_id, row_label = EXCLUDED.row_label, value_min = EXCLUDED.value_min, value_max = EXCLUDED.value_max, value_text = EXCLUDED.value_text, unit = EXCLUDED.unit, condition_text = EXCLUDED.condition_text, observed_on = EXCLUDED.observed_on, confidence = EXCLUDED.confidence, source_kind = EXCLUDED.source_kind, source_ref = EXCLUDED.source_ref, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order, needs_check = EXCLUDED.needs_check, check_reason = EXCLUDED.check_reason, updated_by = 'amie', updated_at = NOW();

INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_11', 'ptt_lst_elements', 'p07', $v$連続運転の社外向け説明（見学会資料）$v$, NULL, NULL, $v$『365日の連続運転が可能なLiSMIC装置が完成』と記載$v$, NULL, $v$濃度・pH・温度の自動制御と液の循環の構成図つき。『可能』という能力の記述で、365日運転した実績の記載はない。$v$, DATE '2026-03-26', 'medium', 'manual', $v$ベンチプラント見学会_関係者用_配布.pdf p.16$v$, $v$社内の運転実績(最長連続運転時間と条件)と並べて、社外資料の表現を確かめる。$v$, 110, 'amie', 'amie', true, $v$見学会資料の『365日の連続運転が可能な装置が完成』は、社内の8月取締役会資料の『運転再開が遅れ連続運転条件を探索中』と食い違う。外部に出す表現をどの実態に合わせるかが変わるため、技術開発部に実際の最長連続運転時間を確認する(「自動制御と連続運転（社内報告）」の行)。$v$)
