INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_12', 'ptt_lst_elements', 'p07', $v$2号機の設計目標（温度・保守周期）$v$, NULL, NULL, $v$運転温度90℃(現行70℃)、11か月運転+1か月内部整備、膜100枚→最大1,000枚(目標)$v$, NULL, $v$まず膜100枚(25枚のスタック4基)を安定稼働させる。TYKで出た配管の沈殿物と、継手・チューブ・ヒーター周りの金属溶出による混入を防ぐ設計にする(見込み)。$v$, DATE '2026-07-22', 'medium', 'estimate', $v$2026-07-22 LiSTie取締役会（Notion文字起こし）ほか$v$, $v$内部を分解洗浄できる構造と、90℃でのポンプ・配管・ヒーターの耐久を確かめる。$v$, 120, 'amie', 'amie', false, NULL)
