INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_13', 'ptt_lst_elements', 'p07', $v$前処理（溶出）の到達点と課題$v$, NULL, NULL, $v$水溶出→電気透析(濃縮・アルカリ化)の流れ。溶出は硫酸で約90%に改善(社内評価は雨→曇り)$v$, NULL, $v$溶出で他の不純物も溶け配管を詰まらせる(匣鉢屑=使用済み耐火容器の屑はケイ素)。廃液は6月に『pH12程度で使いやすい条件』と見たが、実測で回収速度が異様に遅く、中和で不純物が増えスケールが悪化。$v$, DATE '2026-09-09', 'medium', 'meeting', $v$2026-09-09 LiSTie経営会議（Notion文字起こし）ほか$v$, $v$ケイ素などの除去方法(80℃運転でもスケール再発)と、廃液の回収速度が落ちる原因(炭酸イオンの疑い)を実液で確かめる。$v$, 130, 'amie', 'amie', false, NULL)
ON CONFLICT (tech_entry_id) DO UPDATE SET tech_topic_id = EXCLUDED.tech_topic_id, row_label = EXCLUDED.row_label, value_min = EXCLUDED.value_min, value_max = EXCLUDED.value_max, value_text = EXCLUDED.value_text, unit = EXCLUDED.unit, condition_text = EXCLUDED.condition_text, observed_on = EXCLUDED.observed_on, confidence = EXCLUDED.confidence, source_kind = EXCLUDED.source_kind, source_ref = EXCLUDED.source_ref, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order, needs_check = EXCLUDED.needs_check, check_reason = EXCLUDED.check_reason, updated_by = 'amie', updated_at = NOW();

INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_14', 'ptt_lst_elements', 'p07', $v$前処理（濃縮・アルカリ化）の設計$v$, 2, NULL, $v$電気透析(電圧でイオンを膜越しに動かす装置)で溶出液を0.5→2mol/L以上に濃縮し、pH14以上へ(設計値)$v$, $v$mol/L$v$, $v$メーカーの予備試験では水酸化ナトリウムで0.5→約4mol/Lまで濃縮(Li液での実測ではない)。8月資料の目標は溶出0.2M以上・濃縮2M以上(M=mol/L)で、濃縮方法は選定中。$v$, DATE '2026-01-14', 'medium', 'estimate', $v$2026-01-14 LiSTie経営会議（Notion文字起こし）ほか$v$, $v$Li液での濃縮率と、電気透析の目詰まり(不純物の沈殿)を実液で確かめる。$v$, 140, 'amie', 'amie', false, NULL)
ON CONFLICT (tech_entry_id) DO UPDATE SET tech_topic_id = EXCLUDED.tech_topic_id, row_label = EXCLUDED.row_label, value_min = EXCLUDED.value_min, value_max = EXCLUDED.value_max, value_text = EXCLUDED.value_text, unit = EXCLUDED.unit, condition_text = EXCLUDED.condition_text, observed_on = EXCLUDED.observed_on, confidence = EXCLUDED.confidence, source_kind = EXCLUDED.source_kind, source_ref = EXCLUDED.source_ref, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order, needs_check = EXCLUDED.needs_check, check_reason = EXCLUDED.check_reason, updated_by = 'amie', updated_at = NOW();

INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_15', 'ptt_lst_elements', 'p07', $v$後処理（水酸化リチウムの粉末化）$v$, NULL, NULL, $v$水溶液を蒸発・粉砕して粉末にする工程は、窒素雰囲気のグローブボックスで少量を作る計画$v$, NULL, $v$蒸発工程で装置由来の金属(鉄・ガラス・ステンレス成分)が混入する。水分0.05%以下・粒径の要求は『達成見込み』で実測の記載なし。晶析(結晶化)・解砕(粒度調整)の本格設備は計画段階(見込み)。$v$, DATE '2026-09-30', 'medium', 'meeting', $v$2026-09-30 LiSTie経営会議（Notion文字起こし）ほか$v$, $v$間接ヒーターで金属混入が止まるかを元素分析で確かめる。水酸化リチウムは空気中のCO2で炭酸化するため窒素雰囲気で扱う。$v$, 150, 'amie', 'amie', false, NULL)
