INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_16', 'ptt_lst_elements', 'p07', $v$後処理（炭酸リチウム化）$v$, NULL, NULL, $v$顧客候補は水酸化でなく炭酸リチウムを希望。炭酸リチウム用の設備・プロセスの検討を始めた$v$, NULL, $v$LiSMICの回収液は水酸化リチウム側で、炭酸リチウムにはCO2の吹き込みと精製が要る(2025年資料の図)。炭酸リチウム1kg規模のサンプル供給には大量の原液が要る。$v$, DATE '2026-09-30', 'medium', 'meeting', $v$2026-09-30 LiSTie経営会議（Notion文字起こし）$v$, $v$炭酸化の方式(CO2吹き込み等)と、金属配管由来の不純物の混入を確かめる。$v$, 160, 'amie', 'amie', false, NULL)
