INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_17', 'ptt_lst_elements', 'p07', $v$回収量の計測（電流からの推定）$v$, NULL, NULL, $v$リチウム移動量は電流値から換算して見積もる。ICP(元素分析)の実測とはずれが出る$v$, NULL, $v$ずれの大きさ(%)は語られていない。ICP以外の簡易な計測手段がなく、装置として売る水準に届かないため、簡易計測法の開発が必要とされる。$v$, DATE '2026-03-18', 'high', 'meeting', $v$2026-03-18 LiSTie経営会議（Notion文字起こし）$v$, $v$電流換算とICP実測の差の大きさと原因を確かめ、簡易な計測法の候補を絞る。$v$, 170, 'amie', 'amie', false, NULL)
ON CONFLICT (tech_entry_id) DO UPDATE SET tech_topic_id = EXCLUDED.tech_topic_id, row_label = EXCLUDED.row_label, value_min = EXCLUDED.value_min, value_max = EXCLUDED.value_max, value_text = EXCLUDED.value_text, unit = EXCLUDED.unit, condition_text = EXCLUDED.condition_text, observed_on = EXCLUDED.observed_on, confidence = EXCLUDED.confidence, source_kind = EXCLUDED.source_kind, source_ref = EXCLUDED.source_ref, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order, needs_check = EXCLUDED.needs_check, check_reason = EXCLUDED.check_reason, updated_by = 'amie', updated_at = NOW();

INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_18', 'ptt_lst_elements', 'p07', $v$リチウム6の多段濃縮$v$, NULL, NULL, $v$膜1枚でLi-6の割合が高まることは確認済み。QSTは1段を膜20枚で実験し、当社自身は未実施との発言$v$, NULL, $v$天然7.6%を90%へ上げるには約100回の繰り返しと、残液を前段へ戻す循環システムが要る(半分ずつしか移せず量が激減)。システム化に約1年と見込む。$v$, DATE '2026-09-09', 'medium', 'meeting', $v$2026-09-09 LiSTie経営会議（Notion文字起こし）$v$, $v$1段あたりの効率向上が主眼。ラボ規模で90%超を分析値で示せるかを確かめる。QSTの実験規模は社外秘。$v$, 180, 'amie', 'amie', true, $v$「多段カスケードの実証段数」の行『20段のカスケード実証済み』・「20段で到達した濃縮度」の行『20段で90%到達』(口述・記憶ベース)に対し、9月9日の会議は『20段ではなく1段を膜20枚で実験』『当社自身は未実施』、8月12日は『90%超を確認できればトラックレコードになる』と述べ、90%達成の実証が読み取れない。実証済みか計画かで対外説明が変わるため、代表とQSTにQST時代の実験記録(段数・濃縮度・分析値)を確認する。$v$)
ON CONFLICT (tech_entry_id) DO UPDATE SET tech_topic_id = EXCLUDED.tech_topic_id, row_label = EXCLUDED.row_label, value_min = EXCLUDED.value_min, value_max = EXCLUDED.value_max, value_text = EXCLUDED.value_text, unit = EXCLUDED.unit, condition_text = EXCLUDED.condition_text, observed_on = EXCLUDED.observed_on, confidence = EXCLUDED.confidence, source_kind = EXCLUDED.source_kind, source_ref = EXCLUDED.source_ref, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order, needs_check = EXCLUDED.needs_check, check_reason = EXCLUDED.check_reason, updated_by = 'amie', updated_at = NOW();

INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_19', 'ptt_lst_elements', 'p07', $v$中性原液・塩湖かん水への対応（社内）$v$, NULL, NULL, $v$LLTO膜はアルカリ性の原液が前提。中性では電流が流れず、原因は未解明$v$, NULL, $v$塩湖かん水はCa・Mgが多く、pH12付近で大量の沈殿が出て電気透析が詰まる。不純物の結晶化で配管が詰まり、9月末時点で塩湖かん水への移行は技術的に難しいとされる。$v$, DATE '2026-09-30', 'medium', 'meeting', $v$2026-09-30 LiSTie取締役会（Notion文字起こし）ほか$v$, $v$中性でも使える可能性のある別メーカーの膜の試験と、Ca・Mgを吸着剤で除いてから電気透析でアルカリ化する構想を確かめる。$v$, 190, 'amie', 'amie', true, $v$社内の9月末の説明(塩湖かん水は不純物の結晶化で移行が困難、原液はアルカリ性が前提)と、社外資料の『不純物の多い原液にも対応可・元素を選ばず◎』が食い違う。対応できる原液条件の説明が変わるため、技術開発部に実かん水での評価結果を確認する(「不純物の多い原液への対応（社外向け）」の行)。$v$)
ON CONFLICT (tech_entry_id) DO UPDATE SET tech_topic_id = EXCLUDED.tech_topic_id, row_label = EXCLUDED.row_label, value_min = EXCLUDED.value_min, value_max = EXCLUDED.value_max, value_text = EXCLUDED.value_text, unit = EXCLUDED.unit, condition_text = EXCLUDED.condition_text, observed_on = EXCLUDED.observed_on, confidence = EXCLUDED.confidence, source_kind = EXCLUDED.source_kind, source_ref = EXCLUDED.source_ref, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order, needs_check = EXCLUDED.needs_check, check_reason = EXCLUDED.check_reason, updated_by = 'amie', updated_at = NOW();

INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_el_20', 'ptt_lst_elements', 'p07', $v$不純物の多い原液への対応（社外向け）$v$, NULL, NULL, $v$『不純物の多いリチウム源にも対応可』『元素を選ばず◎』と記載$v$, NULL, $v$同じ比較表(2025年のピッチ資料)ではpH調整『要』、低濃度原液『△』と自己評価。塩湖かん水の実サンプル評価は2026年8月時点で進捗なし。$v$, DATE '2026-03-26', 'medium', 'manual', $v$ベンチプラント見学会_関係者用_配布.pdf p.9$v$, $v$実かん水での評価で、許容できる不純物の種類と濃度を数値で確かめる。$v$, 200, 'amie', 'amie', true, $v$見学会・会社紹介・ピッチ資料の『元素を選ばず◎・不純物の多い源にも対応可』が、社内の『中性では電流が流れない・塩湖かん水は結晶化で困難』(9月末)と食い違う。対応できる原液条件の説明が変わるため、技術開発部に実かん水での評価結果を確認する(「中性原液・塩湖かん水への対応（社内）」の行)。$v$)
ON CONFLICT (tech_entry_id) DO UPDATE SET tech_topic_id = EXCLUDED.tech_topic_id, row_label = EXCLUDED.row_label, value_min = EXCLUDED.value_min, value_max = EXCLUDED.value_max, value_text = EXCLUDED.value_text, unit = EXCLUDED.unit, condition_text = EXCLUDED.condition_text, observed_on = EXCLUDED.observed_on, confidence = EXCLUDED.confidence, source_kind = EXCLUDED.source_kind, source_ref = EXCLUDED.source_ref, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order, needs_check = EXCLUDED.needs_check, check_reason = EXCLUDED.check_reason, updated_by = 'amie', updated_at = NOW();

INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_ip_01', 'ptt_lst_patents', 'p07', $v$QST特許の件数（会社紹介資料）$v$, 24, 24, $v$24件(内訳・国・登録状況の記載なし)$v$, $v$件$v$, $v$『LiSMICに関するQST特許24件』とだけ記載。件数がファミリー(同じ発明の各国出願のまとまり)単位か国別かは資料にない。$v$, NULL, 'medium', 'manual', $v$LiSTie会社紹介 p.10（資料内に日付なし）$v$, $v$特許番号の記載例は2023年提案書のコア特許(第6818334号)のみ。$v$, 10, 'amie', 'amie', true, $v$会社紹介資料の『QST特許24件』と、2026-07-08の会議で読み上げた『QST保有は全5件(スタック関連4件)』が食い違う(数え方の違いとみられる)。件数の定義で対外説明の特許基盤の大きさが変わるため、知財担当にQSTの特許一覧(ファミリー・国別)と照合して確認する(「QST特許の件数（経営会議の資料）」の行)。$v$)
