INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_ip_03', 'ptt_lst_patents', 'p07', $v$QSTの外国特許（維持している国）$v$, 6, 6, $v$円筒型・板状型の2種類を、オーストラリア・アルゼンチン・ボリビアで維持(6件)$v$, $v$件$v$, $v$維持年金は1か国6万〜7.6万円、6件で約40万円(2025-11)。2026-07の会議では『QSTの既存特許は南米(アルゼンチン・チリ)で出願済み、欧州は出願なし』と説明された。$v$, DATE '2025-11-26', 'medium', 'meeting', $v$2025-11-26 LiSTie経営会議（Notion文字起こし）$v$, $v$円筒型（イオン伝導体の筒を多数並べる型）・板状型（板を並べる型）は会議の聞き取りからの読み。$v$, 30, 'amie', 'amie', true, $v$維持年金の記録の国(オーストラリア・アルゼンチン・ボリビア)と、2026-07の説明の国(アルゼンチン・チリ)が一致しない。QSTの権利がどの国に及ぶかで欧州・南米・豪州の出願要否の判断が変わるため、知財担当にQST外国特許の国別一覧を確認する。$v$)
