VALUES ('pte_lst_ip_05', 'ptt_lst_patents', 'p07', $v$小面積電極の特許（QST出願・PCT段階）$v$, NULL, NULL, $v$電極面積(高価な金属の使用量)を減らしても回収速度は平板電極並み$v$, NULL, $v$従来は膜と同面積の電極。針金をばね状に巻く形などで面積を減らす。出願人はQSTで、LiSTieは出願人ではなく、PCT出願分がQSTからの現物出資(特許での出資=バックグラウンドIP)の対象。$v$, DATE '2025-11-26', 'high', 'meeting', $v$2025-11-26 LiSTie経営会議（Notion文字起こし）$v$, $v$PCT=複数国へ一括で出願できる国際出願。装置の中核に寄与する特許と説明。$v$, 50, 'amie', 'amie', false, NULL)
