VALUES ('pte_lst_mm_01', 'ptt_lst_membrane', 'p07', $v$膜1枚あたりの目標電流$v$, 10, 10, $v$膜1枚で10 A（目標）$v$, $v$A$v$, $v$目標。コストを成り立たせる回収速度の目安で、2号機のKPIも膜1枚10 A相当。現状の運転は10 Aに届いていない$v$, DATE '2026-07-22', 'medium', 'estimate', $v$2026-07-22 LiSTie取締役会（Notion文字起こし）$v$, $v$2025年11月26日はコスト3ドル未満の必須条件と説明（値の正本はコスト試算ページ）$v$, 60, 'amie', 'amie', false, NULL)
