INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_mm_02', 'ptt_lst_membrane', 'p07', $v$高電流通電での膜の割れ$v$, NULL, NULL, $v$10 Aのような高電流を流すと膜が割れる事象が発生$v$, NULL, $v$QST共同の試験機でも発生。2026年8月26日に高電流で割れると結論し、回収速度（電流）を下げて運転する方針$v$, DATE '2026-08-26', 'high', 'meeting', $v$2026-08-26 LiSTie取締役会（Notion文字起こし）$v$, $v$同じLi量を得るには膜枚数が増えるため、コストを再計算中$v$, 70, 'amie', 'amie', true, $v$「連続通電で流せる電流」の行 は連続通電で〜10 Aとするが、10 A級で膜が割れる報告（2025年11月・2026年8月）がある。「流せる」が短時間の到達値か長期運転の限界かでこの表の読み方が変わるため、開発責任者に確認。$v$)
