VALUES ('pte_lst_mm_06', 'ptt_lst_membrane', 'p07', $v$歪み・割れの原因仮説と対策案$v$, NULL, NULL, $v$膜の中心部にLiが集中して流れる環境が第一の疑い$v$, NULL, $v$歪みは酸処理の時点で発生し通電で拡大。対策案は電極を周囲に置く・酸処理を両面にする・膜を厚くする・回収液側の流速を上げる$v$, DATE '2026-01-21', 'medium', 'meeting', $v$2026-01-21 LiSTie取締役会（Notion文字起こし）$v$, $v$QSTのデータでも流れが中心部に集中。仮説であり他の原因も見ている（2025年11月26日時点）$v$, 110, 'amie', 'amie', false, NULL)
