VALUES ('pte_lst_mm_09', 'ptt_lst_membrane', 'p07', $v$高Li濃度時の結晶析出$v$, NULL, NULL, $v$回収液側のLi濃度が電流値換算より濃いと、膜面に水酸化Liの結晶が析出$v$, NULL, $v$Liが流れなくなるだけでなく膜を全交換する必要が出る。実際に起きたか想定リスクかは明言されていない$v$, DATE '2026-03-18', 'medium', 'meeting', $v$2026-03-18 LiSTie経営会議（Notion文字起こし）$v$, NULL, 140, 'amie', 'amie', false, NULL)
