VALUES ('pte_lst_mm_10', 'ptt_lst_membrane', 'p07', $v$持ち帰り後の開封所見$v$, NULL, NULL, $v$電圧が上がったセルは開封すると異常なし。ラボで再組立てすると析出物と電極の黒化$v$, NULL, $v$TYK搬入前・搬入時には析出物は出なかった。回収液側電極の黒化は酸化と見ている。原因は不明$v$, DATE '2026-06-17', 'medium', 'meeting', $v$2026-06-17 LiSTie経営会議（Notion文字起こし）$v$, NULL, 150, 'amie', 'amie', false, NULL)
