VALUES ('pte_lst_mm_13', 'ptt_lst_membrane', 'p07', $v$逆電圧印加による性能回復$v$, NULL, NULL, $v$通常と逆向きの電圧をかけると、流れの悪くなった膜の性能が回復する傾向$v$, NULL, $v$TYK搬入セルの流量悪化への対応で観察。回復の程度や繰り返せるかの数値は示されていない$v$, DATE '2026-06-24', 'medium', 'meeting', $v$2026-06-24 LiSTie取締役会（Notion文字起こし）$v$, NULL, 170, 'amie', 'amie', false, NULL)
