VALUES ('pte_lst_pt_06', 'ptt_lst_pretreat', 'p07', $v$匣鉢屑の水溶出の方式$v$, NULL, NULL, $v$匣鉢屑を水に浸してLiを水側へ溶かし、遠心脱水で水を分離（屑は槽内に残す）$v$, NULL, $v$ドラム缶のような容器を回転させるロッキングミキサー構造でカタログ品ではない。回転ドラム式の水溶出装置2台をTYKへ搬送$v$, DATE '2025-12-03', 'medium', 'meeting', $v$2025-12-03 LiSTie経営会議（Notion文字起こし）$v$, NULL, 140, 'amie', 'amie', false, NULL)
