VALUES ('pte_lst_pt_07', 'ptt_lst_pretreat', 'p07', $v$匣鉢の溶出率とTYKの目標$v$, NULL, 20, $v$TYKの目標: 匣鉢に残るLiを20%以下。現状は水で約6割しか溶けない$v$, $v$%$v$, $v$残り約2割を溶かすには硫酸を使うプロセスの開発が必要$v$, DATE '2026-08-26', 'medium', 'meeting', $v$2026-08-26 LiSTie取締役会（Notion文字起こし）$v$, $v$「6割」は溶出率と読める発言$v$, 150, 'amie', 'amie', false, NULL)
