VALUES ('pte_lst_pt_12', 'ptt_lst_pretreat', 'p07', $v$ケイ素析出で電気透析の流量低下$v$, NULL, NULL, $v$電気透析の流量が約半分に低下。流路の白い沈殿はケイ素と分析で判明$v$, NULL, $v$TYKの匣鉢屑を溶かした水溶出液のLi濃縮装置で発生。ケイ素は匣鉢屑特有で、ブラックマスでは入らず問題にならない見込み$v$, DATE '2026-06-10', 'high', 'meeting', $v$2026-06-10 LiSTie経営会議（Notion文字起こし）$v$, NULL, 200, 'amie', 'amie', false, NULL)
