INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_pt_16', 'ptt_lst_pretreat', 'p07', $v$硫酸溶出の副作用（不純物）$v$, NULL, NULL, $v$硫酸でLi溶出率は上がるが他の不純物も溶け、TYKでは析出して配管が詰まった$v$, NULL, $v$LiSMICが詰まる原因は不純物元素の濃度が高くなること。中和剤を入れると不純物が余計に増える。不純物の扱いが課題$v$, DATE '2026-09-09', 'medium', 'meeting', $v$2026-09-09 LiSTie経営会議（Notion文字起こし）$v$, NULL, 240, 'amie', 'amie', false, NULL)
