INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_pt_18', 'ptt_lst_pretreat', 'p07', $v$日亜化学の廃液の性状$v$, NULL, NULL, $v$pH約12のアルカリ性の液体（溶かす工程が不要）。Li濃度は薄い$v$, NULL, $v$電気透析でLi濃度を高めれば足りる。薄いため日亜側で約5倍濃縮して受け取る方向で調整。硫酸イオンを含み前処理への影響を検証する$v$, DATE '2026-06-24', 'medium', 'meeting', $v$2026-06-24 LiSTie経営会議（Notion文字起こし）$v$, $v$pH12は「LiSMICが好むpH12ぐらい」との発言。硫酸イオンの検証は7月22日に言及$v$, 250, 'amie', 'amie', true, $v$2023年提案書はpH13.5以上を前提、2026年6月24日の会議は日亜化学の排液pH12程度を「好ましい条件」と説明。LiSMICが必要とするpHの下限で日亜排液に追加のpH調整が要るかが変わるため、前処理担当に確認。$v$)
