VALUES ('pte_lst_pt_19', 'ptt_lst_pretreat', 'p07', $v$日亜廃液のpH制御（14超）$v$, NULL, NULL, $v$pHが14を超えると、なぜかそれ以上pHが上がらない現象$v$, NULL, $v$pHをコントロールする工程で苦戦。原因を調査中$v$, DATE '2026-09-16', 'high', 'meeting', $v$2026-09-16 LiSTie経営会議（Notion文字起こし）$v$, NULL, 260, 'amie', 'amie', false, NULL)
