INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_pt_22', 'ptt_lst_pretreat', 'p07', $v$廃液の速度低下と硫酸添加の回復$v$, NULL, NULL, $v$廃液に硫酸を加えると通常の回収速度に戻った（予備実験）$v$, NULL, $v$日亜化学の廃液は最初は回収速度が低かった。硫酸は使う必要があるが、戻るならとりあえずよいとの見方$v$, DATE '2026-09-09', 'medium', 'meeting', $v$2026-09-09 LiSTie経営会議（Notion文字起こし）$v$, $v$9月2日の中和策（水酸化バリウム等）とは別の手段$v$, 290, 'amie', 'amie', true, $v$9月2日は硫酸イオンと炭酸Liを含む廃液で回収速度が低下（「硫酸・炭酸リチウムを含む廃液での回収速度」の行）、9月9日はさらに硫酸を加えると回復と報告。速度低下の主因が炭酸か硫酸かで硫酸添加・中和・吸着剤のどれを採るかが変わるため、前処理担当に確認。$v$)
