VALUES ('pte_lst_pt_24', 'ptt_lst_pretreat', 'p07', $v$中性かん水のアルカリ化手段$v$, NULL, NULL, $v$アルカリ水電解型の電解処理装置が最有力。吸着剤でLiを一度吸着してから電解する案もある$v$, NULL, $v$中性の原液はアルカリ性にする操作が必要。リサイクル原料の前処理は想定内のコスト（5月27日）。廃液のアルカリ化にも電解装置が要る（9月16日）$v$, DATE '2026-05-27', 'medium', 'meeting', $v$2026-05-27 LiSTie取締役会（Notion文字起こし）$v$, $v$試験段階でノウハウの蓄積が必要$v$, 310, 'amie', 'amie', false, NULL)
