VALUES ('pte_lst_po_06', 'ptt_lst_posttreat', 'p07', $v$グローブボックス（窒素で空気を遮る作業箱）$v$, NULL, NULL, $v$水酸化リチウム粉末の蒸発・粉砕の2工程に各1台、計2台のグローブボックス（窒素で空気を遮る作業箱）を使う計画$v$, NULL, $v$粉末の製造装置は当面入れず、少量のサンプルを自社で蒸発・粉砕する$v$, DATE '2026-08-26', 'high', 'meeting', $v$2026-08-26 LiSTie経営会議（Notion文字起こし）$v$, NULL, 30, 'amie', 'amie', false, NULL)
