VALUES ('pte_lst_po_07', 'ptt_lst_posttreat', 'p07', $v$水酸化リチウムのCO2吸収$v$, NULL, NULL, $v$空気中のCO2を吸ってすぐ炭酸リチウムになるため、窒素雰囲気の箱で作業する$v$, NULL, $v$TYKに持ち込む前のLiSMIC試験も、大気に触れて炭酸リチウムができない環境（窒素雰囲気）で実施していた$v$, DATE '2026-08-12', 'high', 'meeting', $v$2026-08-12 LiSTie経営会議（Notion文字起こし）$v$, NULL, 40, 'amie', 'amie', false, NULL)
