VALUES ('pte_lst_lm_03', 'ptt_lst_limits', 'p07', $v$中性の原液のアルカリ化$v$, NULL, NULL, $v$中性・酸性の原液は、アルカリ化の工程（アルカリ水電解型の電解処理装置）が必須$v$, NULL, $v$酸性の溶液も同じ工程が必要$v$, DATE '2026-05-27', 'medium', 'estimate', $v$2026-05-27 LiSTie取締役会（Notion文字起こし）$v$, $v$追加費用の見立ては水酸化リチウム1 kgあたり約500円（設備費約300円＋運転費約200円、ほぼ電気代。2026-05-27の会議）。コスト試算ページには未登録$v$, 30, 'amie', 'amie', false, NULL)
