INSERT INTO project_tech_entries (tech_entry_id, tech_topic_id, project_id, row_label, value_min, value_max, value_text, unit, condition_text, observed_on, confidence, source_kind, source_ref, note, sort_order, created_by, updated_by, needs_check, check_reason)
VALUES ('pte_lst_un_14', 'ptt_lst_unit', 'p07', $v$ベンチ実証機の運転温度$v$, 70, 90, $v$現行のベンチ実証機は70℃。2号機は90℃での安定運転が目標$v$, $v$℃$v$, $v$運転温度を上げてスタックを入れられるようにする狙い$v$, DATE '2026-07-22', 'medium', 'meeting', $v$2026-07-22 LiSTie取締役会（Notion文字起こし）$v$, NULL, 170, 'amie', 'amie', true, $v$「TYK実証の80℃スケール」の行 は「TYK実証の80℃スケール」だが、9/9の記録は「当社ラボの80℃運転」でスケールが再発生とあり、7/22は現行ベンチ実証機を70℃と説明。TYKの運転温度が70℃か80℃か、80℃はラボ試験かで、スケールの再発条件の理解が変わる。開発に確認する。$v$)
