UPDATE project_tech_entries SET needs_check = true, check_reason = $v$会議では日亜化学の原料は正極材の洗浄排液（pH約12）と匣鉢くずとして説明されており、「コバルトリサイクル廃液」は聞き取りの違いの可能性がある。ラボに届いた液の種類を前処理担当に確かめる$v$, updated_by = 'amie', updated_at = NOW() WHERE tech_entry_id = 'pte_lst_pre_nichia' AND project_id = 'p07';

UPDATE project_tech_entries SET needs_check = true, check_reason = $v$2026-09-09の会議で「20段ではなく1段あたり膜20枚」「当社自身は多段を未実施」との説明があり、この行の「20段完了」と食い違う。QST時代の実験記録（段数・濃縮度・分析値）を代表とQSTに確かめる$v$, updated_by = 'amie', updated_at = NOW() WHERE tech_entry_id = 'pte_lst_li6_stage' AND project_id = 'p07';

UPDATE project_tech_entries SET needs_check = true, check_reason = $v$資料（会社紹介 p.13・SBIR提案書 2023年）はセラミックスのイオン伝導体の膜の中での6Liと7Liの速度差で説明しており、この行の「イオン液体と隔膜」と方式の書き方が違う。どちらの方式で濃縮するか（両方あるのか）を開発に確かめる$v$, updated_by = 'amie', updated_at = NOW() WHERE tech_entry_id = 'pte_lst_li6_method' AND project_id = 'p07';

-- 仕上がりの確認: 区分は6つ、旧区分（膜（LiSMIC）・前処理・リチウム6濃縮・装置（ユニット））は残らない
DO $$
DECLARE n_topics int; n_rows int; n_old int;
BEGIN
  SELECT count(*) INTO n_topics FROM project_tech_topics WHERE project_id = 'p07' AND tech_domain NOT IN ('競合比較','ビジネスモデル');
  SELECT count(*) INTO n_rows FROM project_tech_entries e JOIN project_tech_topics t USING (tech_topic_id)
    WHERE t.project_id = 'p07' AND t.tech_domain NOT IN ('競合比較','ビジネスモデル');
  SELECT count(*) INTO n_old FROM project_tech_topics WHERE project_id = 'p07' AND tech_domain IN ('膜（LiSMIC）','前処理','リチウム6濃縮','装置（ユニット）');
  IF n_topics <> 17 OR n_old <> 0 THEN
    RAISE EXCEPTION '453: トピック数 % / 旧区分 % が想定と違う', n_topics, n_old;
  END IF;
  RAISE NOTICE '453: LiSTie 技術タブ トピック % / 行 %', n_topics, n_rows;
END $$;

COMMIT;
